// Keeps only leads created yesterday (workflow timezone) and collapses them into ONE item
// with counts, a plain-text list for the AI prompt and an HTML table for the email.
const cfg = $('Config').first().json.cfg;
const tz = $workflow.settings?.timezone ?? 'UTC';

const ymd = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const yesterday = ymd(new Date(Date.now() - 24 * 60 * 60 * 1000));

const rows = $input.all()
  .map((i) => i.json)
  .filter((r) => r && r.email) // drop the empty placeholder item from 'Always output data'
  .filter((r) => String(r.created_date ?? String(r.created_at ?? '').slice(0, 10)) === yesterday)
  .map((r) => ({
    name: r.name ?? '',
    email: r.email ?? '',
    company: r.company ?? '',
    source: r.source ?? '',
    score: Number(r.score ?? 0),
    message: String(r.message ?? '').slice(0, 300),
  }))
  .sort((a, b) => b.score - a.score);

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const plainList = rows
  .map((r, i) => `${i + 1}. ${r.name} <${r.email}> — ${r.company || 'no company'} — score ${r.score} — via ${r.source}\n   "${r.message}"`)
  .join('\n');

const tableRows = rows
  .map((r) => `<tr><td>${esc(r.name)}</td><td>${esc(r.company)}</td><td><a href="mailto:${esc(r.email)}">${esc(r.email)}</a></td><td style=\"text-align:center\">${r.score}</td><td>${esc(r.message)}</td></tr>`)
  .join('');

const hot = rows.filter((r) => r.score >= 60).length;
const avg = rows.length ? Math.round(rows.reduce((s, r) => s + r.score, 0) / rows.length) : 0;

return [{
  json: {
    cfg,
    date: yesterday,
    count: rows.length,
    hot,
    avgScore: avg,
    leads: rows,
    plainList,
    tableRows,
  },
}];

const agg = $('Filter Yesterday & Aggregate').first().json;
const ai = String($input.first().json.text ?? $input.first().json.output ?? '').trim();
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const subject = `📊 ${agg.count} new lead${agg.count === 1 ? '' : 's'} on ${agg.date} · ${agg.hot} hot`;

const html = `<!doctype html><html><body style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1f2937;max-width:720px;margin:0 auto;padding:24px;line-height:1.5">
<h2 style="margin:0 0 4px">Daily lead digest — ${esc(agg.date)}</h2>
<p style="margin:0 0 20px;color:#6b7280">${agg.count} new · ${agg.hot} hot (score ≥ 60) · average score ${agg.avgScore}</p>
<div style="background:#eef2ff;border-left:4px solid #6366f1;padding:14px 18px;border-radius:6px;white-space:pre-wrap;margin-bottom:24px">${esc(ai)}</div>
<table style="border-collapse:collapse;width:100%;font-size:13px">
<thead><tr style="background:#f3f4f6;text-align:left"><th style="padding:8px">Name</th><th style="padding:8px">Company</th><th style="padding:8px">Email</th><th style="padding:8px">Score</th><th style="padding:8px">Message</th></tr></thead>
<tbody>${agg.tableRows.replace(/<td/g, '<td style="padding:8px;border-top:1px solid #e5e7eb;vertical-align:top"')}</tbody>
</table>
<p style="font-size:12px;color:#9ca3af;margin-top:28px">Generated automatically by n8n · ${esc(agg.cfg.companyName)}</p>
</body></html>`;

const telegram = `📊 <b>Daily digest ${esc(agg.date)}</b>\n${agg.count} new leads · ${agg.hot} hot 🔥\n\n${esc(ai).slice(0, 1500)}`;

return [{ json: { cfg: agg.cfg, subject, html, telegram } }];

const agg = $input.first().json;
const subject = `📊 No new leads on ${agg.date}`;
const html = `<!doctype html><html><body style="font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">
<h2>Daily lead digest — ${agg.date}</h2>
<p>No new leads came in yesterday. The intake workflow is running normally (this email is the heartbeat).</p>
<p style="font-size:12px;color:#9ca3af">Generated automatically by n8n · ${agg.cfg.companyName}</p>
</body></html>`;
const telegram = `📊 <b>Daily digest ${agg.date}</b>\nNo new leads yesterday. Pipeline healthy ✅`;
return [{ json: { cfg: agg.cfg, subject, html, telegram } }];
